    file,
    ...publicationByteForms(safeBytes(root, file)),
  }))
}
export function sourceSetSha256(inputs) {
  return sha256(
    JSON.stringify(
      inputs
        .map((x) => ({ file: x.file, sha256: x.canonicalSha256 }))
        .sort((a, b) => a.file.localeCompare(b.file, 'en')),
    ),
  )
}
